    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d >= c.MinSum());
        require(_am <= d);
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.Collect(_am); if (__ESBMC_reverted()) return;
        reverted = false;
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(!reverted && afterBal + _am == beforeBal);
    }
    receive() external payable {}
