pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 d, uint256 _am) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d >= c.MinSum());
        vm.assume(_am <= d);
        try c.Deposit{value: d}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool reverted;
        try c.Collect(_am) {} catch { return; }
        reverted = false;
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(!reverted && afterBal + _am == beforeBal);
    }

    function testFuzz_run(uint256 d, uint256 _am) public {
        _run(d, _am);
    }

    receive() external payable {}
}
